<template><main class="admin-content" v-if="q"><div class="mb-6 flex flex-wrap items-start justify-between gap-3"><div><NuxtLink to="/admin/manual-quotes" class="text-sm font-bold text-blue-600">← Manual Quotes</NuxtLink><h1 class="mt-2 text-3xl font-black">{{q.quote_number}}</h1><p class="text-slate-500">{{q.sales_customers?.company_name||q.sales_customers?.full_name}}</p></div><div class="flex flex-wrap gap-2"><a :href="`/api/admin/manual-quotes/${q.id}/pdf`" class="btn-secondary">Download PDF</a><button class="btn-secondary" @click="duplicate">Duplicate</button><button class="btn-primary" @click="email">Email Quote</button></div></div><div v-if="msg" class="mb-4 rounded-lg bg-emerald-50 p-3 text-emerald-700">{{msg}}</div><div v-if="err" class="mb-4 rounded-lg bg-red-50 p-3 text-red-700">{{err}}</div>
<section class="admin-panel p-5"><div class="grid gap-4 md:grid-cols-4"><label><span class="label">Customer</span><select v-model="q.customer_id" class="input"><option v-for="c in customers" :value="c.id">{{c.company_name?`${c.company_name} — `:''}}{{c.full_name}}</option></select></label><label><span class="label">Status</span><select v-model="q.status" class="input"><option v-for="s in statuses" :value="s">{{s}}</option></select></label><label><span class="label">Issue Date</span><input v-model="q.issue_date" type="date" class="input"></label><label><span class="label">Valid Until</span><input v-model="q.expires_at" type="date" class="input"></label></div></section>
<section class="admin-panel mt-5 p-5"><div class="flex flex-wrap items-end justify-between gap-3"><div><h2 class="text-xl font-black">Quote Items</h2><p class="text-sm text-slate-500">Add products from your website or add a manual service/custom item.</p></div><div class="flex gap-2"><button class="btn-secondary" @click="addManual('service')">+ Service</button><button class="btn-secondary" @click="addManual('custom')">+ Custom Item</button></div></div><div class="relative mt-4"><input v-model="productSearch" class="input" placeholder="Search website products to add…" @focus="showProducts=true"><div v-if="showProducts&&filteredProducts.length" class="absolute z-20 mt-1 max-h-72 w-full overflow-auto rounded-lg border bg-white shadow-xl"><button v-for="p in filteredProducts.slice(0,20)" :key="p.id" class="flex w-full items-center gap-3 border-b p-3 text-left hover:bg-blue-50" @click="configureProduct(p)"><div class="h-14 w-14 shrink-0 overflow-hidden rounded-lg border bg-white"><img v-if="productImage(p)" :src="productImage(p)" :alt="p.name" class="h-full w-full object-contain"><div v-else class="grid h-full place-items-center text-[10px] text-slate-400">No image</div></div><div class="min-w-0 flex-1"><strong class="block truncate">{{p.name}}</strong><span class="block text-xs text-slate-500"><span v-if="p.product_code">SKU: {{p.product_code}} • </span>Stock: {{p.stock??0}}</span></div><span class="shrink-0 font-bold">{{money(p.price)}}</span></button></div></div>
<div class="mt-5 overflow-x-auto"><table class="min-w-[900px] w-full text-sm"><thead><tr class="bg-slate-50 text-left"><th class="p-2 w-20">Image</th><th class="p-2 w-40">SKU / Code</th><th class="p-2">Description</th><th class="p-2 w-24">Qty</th><th class="p-2 w-36">Unit Price</th><th class="p-2 w-28">Discount %</th><th class="p-2 w-36 text-right">Line Total</th><th class="p-2 w-20"></th></tr></thead><tbody><tr v-for="(i,n) in q.manual_quote_items" :key="n" class="border-t align-top"><td class="p-2"><div class="h-14 w-14 overflow-hidden rounded-lg border bg-white"><img v-if="quoteItemImage(i)" :src="quoteItemImage(i)" :alt="i.product_name||'Product'" class="h-full w-full object-contain"><div v-else class="grid h-full place-items-center text-[9px] text-slate-400">{{i.product_id?'No image':'—'}}</div></div></td><td class="p-2"><input v-model="i.sku" class="input" placeholder="SKU / code"></td><td class="p-2"><textarea v-model="i.description" rows="2" class="input resize-y" :placeholder="i.product_name || 'Description'"></textarea></td><td class="p-2"><input v-model.number="i.quantity" type="number" min="0.01" step="1" class="input"></td><td class="p-2"><input v-model.number="i.unit_price" type="number" min="0" step="0.01" class="input"></td><td class="p-2"><input v-model.number="i.discount_percent" type="number" min="0" max="100" step="0.01" class="input"></td><td class="p-2 text-right font-bold">{{money(lineTotal(i))}}</td><td class="p-2 text-right"><button class="text-red-600" @click="q.manual_quote_items.splice(n,1)">Remove</button></td></tr></tbody></table></div></section>
<section class="mt-5 grid gap-5 lg:grid-cols-[1fr_380px]"><div class="admin-panel p-5"><label><span class="label">Customer Notes / Quote Notes</span><textarea v-model="q.customer_notes" rows="5" class="input" placeholder="Visible on the PDF quote"></textarea></label><label class="mt-4 block"><span class="label">Private Internal Notes</span><textarea v-model="q.internal_notes" rows="4" class="input"></textarea></label></div><div class="admin-panel p-5"><label><span class="label">Delivery Method</span><select v-model="q.delivery_method" class="input"><option value="none">None</option><option value="pickup">Store Pickup</option><option value="delivery">Delivery</option></select></label><div v-if="q.delivery_method==='delivery'" class="mt-3"><label class="block"><span class="label">Delivery Postcode</span><div class="flex gap-2"><input v-model="deliveryPostcode" inputmode="numeric" maxlength="4" class="input" placeholder="Postcode"><button type="button" class="btn-secondary whitespace-nowrap" :disabled="freightLoading" @click="calculateQuoteFreight">{{freightLoading?'Calculating…':'Calculate'}}</button></div></label><label v-if="freightRates.length>1" class="mt-3 block"><span class="label">Postage Service</span><select v-model="selectedFreightCode" class="input" @change="applySelectedFreight"><option v-for="r in freightRates" :key="r.code" :value="r.code">{{r.name}} — {{money(r.price)}}</option></select></label><p v-if="freightMessage" class="mt-2 text-xs font-semibold text-slate-500">{{freightMessage}}</p></div><label class="mt-3 block"><span class="label">Delivery Amount</span><input v-model.number="q.delivery_amount" type="number" min="0" step="0.01" class="input"></label><label class="mt-3 block"><span class="label">Quote Discount ($)</span><input v-model.number="q.discount_amount" type="number" min="0" step="0.01" class="input"></label><div class="mt-5 space-y-2 border-t pt-4"><div class="flex justify-between"><span>Subtotal</span><strong>{{money(grossItemsTotal)}}</strong></div><div v-if="lineDiscountTotal>0" class="flex justify-between text-emerald-700"><span>Line Discounts</span><strong>-{{money(lineDiscountTotal)}}</strong></div><div v-if="Number(q.discount_amount||0)>0" class="flex justify-between text-emerald-700"><span>Quote Discount</span><strong>-{{money(q.discount_amount)}}</strong></div><div v-if="Number(q.delivery_amount||0)>0" class="flex justify-between"><span>Delivery</span><strong>{{money(q.delivery_amount)}}</strong></div><div class="flex justify-between"><span>GST included</span><strong>{{money(total/11)}}</strong></div><div class="flex justify-between text-xl"><span>Total</span><strong>{{money(total)}}</strong></div></div></div></section><div class="sticky bottom-3 mt-6 flex justify-end"><button class="btn-primary shadow-lg" :disabled="saving" @click="save">{{saving?'Saving…':'Save Quote'}}</button></div></main><main v-else class="admin-content">Loading quote…</main><Teleport to="body"><div v-if="configProduct" class="fixed inset-0 z-[9999] flex items-center justify-center bg-slate-950/60 p-4" @click.self="closeConfigurator"><div class="max-h-[90vh] w-full max-w-2xl overflow-y-auto rounded-2xl bg-white p-6 shadow-2xl"><div class="flex justify-between gap-4"><div class="flex min-w-0 items-center gap-4"><div class="h-20 w-20 shrink-0 overflow-hidden rounded-xl border bg-white"><img v-if="productImage(configProduct)" :src="productImage(configProduct)" :alt="configProduct.name" class="h-full w-full object-contain"><div v-else class="grid h-full place-items-center text-xs text-slate-400">No image</div></div><div class="min-w-0"><p class="text-xs font-bold uppercase text-blue-600">Configure quote item</p><h2 class="text-xl font-black">{{configProduct.name}}</h2></div></div><button @click="closeConfigurator" class="text-2xl">×</button></div><div v-if="configLoading" class="py-8 text-center">Loading options…</div><template v-else><label v-if="configVariants.length" class="mt-5 block"><span class="label">Variant</span><select v-model="selectedVariantId" class="input"><option value="">Base product — {{money(configProduct.price)}}</option><option v-for="v in configVariants.filter((x:any)=>x.active!==false)" :key="v.id" :value="String(v.id)">{{v.name}} — {{money(variantPrice(v))}}</option></select></label><div v-for="g in configAddons.filter((x:any)=>x.active!==false)" :key="g.id" class="mt-5 rounded-xl border p-4"><div class="font-black">{{g.name}} <span v-if="g.required" class="text-xs text-red-600">Required</span></div><label v-for="o in (g.product_addon_options||[]).filter((x:any)=>x.active!==false)" :key="o.id" class="mt-2 flex items-center justify-between rounded-lg border p-3"><span class="flex gap-2"><input v-if="g.selection_type==='multiple'" v-model="selectedAddonIds" type="checkbox" :value="String(o.id)"><input v-else type="radio" :name="'qa'+g.id" :checked="selectedAddonForGroup(g)===String(o.id)" @change="selectSingleAddon(g,o)">{{o.name}}</span><b v-if="Number(o.price||0)">+ {{money(o.price)}}</b></label></div><div v-if="configError" class="mt-4 rounded-lg bg-red-50 p-3 text-red-700">{{configError}}</div><div class="mt-6 flex items-center justify-between border-t pt-5"><div><small>Configured price</small><div class="text-2xl font-black">{{money(configuredPrice)}}</div><div v-if="quotePricingLevel" class="mt-1 text-xs font-bold text-blue-600">{{quotePricingLevel.name}} price level</div><div v-if="standardSitePrice!==null && standardSitePrice>Number(sitePrice||0)" class="mt-1 text-sm text-slate-500">Standard <span class="line-through">{{money(standardSitePrice)}}</span></div></div><button class="btn-primary" @click="addConfiguredProduct">Add to Quote</button></div></template></div></div></Teleport></template>
<script setup lang="ts">
definePageMeta({layout:'admin',middleware:['admin']});
const{adminFetch}=useAdminFetch(),route=useRoute();const q=ref<any>(null),customers=ref<any[]>([]),products=ref<any[]>([]),productSearch=ref(''),showProducts=ref(false),saving=ref(false),msg=ref(''),err=ref('');
const configProduct=ref<any>(null),configVariants=ref<any[]>([]),configAddons=ref<any[]>([]),configLoading=ref(false),configError=ref(''),selectedVariantId=ref(''),selectedAddonIds=ref<string[]>([]),sitePrice=ref<number|null>(null),standardSitePrice=ref<number|null>(null),quotePricingLevel=ref<any>(null),deliveryPostcode=ref(''),freightRates=ref<any[]>([]),selectedFreightCode=ref(''),freightLoading=ref(false),freightMessage=ref('');
const statuses=['draft','sent','accepted','declined','expired','converted'];const money=(v:any)=>new Intl.NumberFormat('en-AU',{style:'currency',currency:'AUD'}).format(Number(v||0));const lineTotal=(i:any)=>Number(i.quantity||0)*Number(i.unit_price||0)*(1-Number(i.discount_percent||0)/100);const itemsTotal=computed(()=>q.value?.manual_quote_items?.reduce((x:number,i:any)=>x+lineTotal(i),0)||0);const grossItemsTotal=computed(()=>q.value?.manual_quote_items?.reduce((x:number,i:any)=>x+Number(i.quantity||0)*Number(i.unit_price||0),0)||0);const lineDiscountTotal=computed(()=>Math.max(0,grossItemsTotal.value-itemsTotal.value));const total=computed(()=>Math.max(0,itemsTotal.value+Number(q.value?.delivery_amount||0)-Number(q.value?.discount_amount||0)));const filteredProducts=computed(()=>{const x=productSearch.value.trim().toLowerCase();return x?products.value.filter((p:any)=>`${p.name} ${p.slug||''} ${p.sku||p.product_code||''}`.toLowerCase().includes(x)):[]});
function productImage(p:any){const images=p?.images;if(!Array.isArray(images)||!images.length)return '';const first=images.find((x:any)=>typeof x==='string'?x.trim():x?.url||x?.image_url||x?.src);if(typeof first==='string')return first;return first?.url||first?.image_url||first?.src||''}
function quoteItemImage(i:any){if(!i?.product_id)return '';const p=products.value.find((x:any)=>String(x.id)===String(i.product_id));return productImage(p)}
function customerPostcode(){const c=customers.value.find((x:any)=>String(x.id)===String(q.value?.customer_id));const address=String(c?.delivery_address||c?.billing_address||'');const matches=address.match(/\b\d{4}\b/g);return matches?.at(-1)||''}
function freightItems(){return (q.value?.manual_quote_items||[]).filter((i:any)=>i.product_id&&Number(i.quantity)>0).map((i:any)=>({id:Number(i.product_id),quantity:Math.max(1,Math.round(Number(i.quantity||1)))}))}
function applySelectedFreight(){const r=freightRates.value.find((x:any)=>x.code===selectedFreightCode.value);if(r)q.value.delivery_amount=Number(r.price||0)}
async function calculateQuoteFreight(){freightMessage.value='';freightRates.value=[];const postcode=String(deliveryPostcode.value||customerPostcode()).trim();deliveryPostcode.value=postcode;if(!/^\d{4}$/.test(postcode)){freightMessage.value='Enter a valid 4-digit delivery postcode.';return}const items=freightItems();if(!items.length){freightMessage.value='Add at least one website product before calculating postage.';return}freightLoading.value=true;try{const result:any=await adminFetch('/api/admin/manual-quotes/freight',{method:'POST',body:{postcode,items}});freightRates.value=Array.isArray(result?.rates)?result.rates:[];if(freightRates.value.length){selectedFreightCode.value=freightRates.value[0].code;applySelectedFreight();freightMessage.value=freightRates.value.length===1?`${freightRates.value[0].name} selected automatically.`:'Postage calculated. Select the service you want to quote.'}else freightMessage.value='No postage services were returned.'}catch(e:any){freightMessage.value=e?.data?.statusMessage||e.message||'Unable to calculate postage.'}finally{freightLoading.value=false}}
async function load(){[q.value,customers.value,products.value]=await Promise.all([adminFetch(`/api/admin/manual-quotes/${route.params.id}`),adminFetch('/api/admin/customers'),adminFetch('/api/admin/products')]) as any;deliveryPostcode.value=customerPostcode()}
const selectedVariant=computed(()=>configVariants.value.find((v:any)=>String(v.id)===selectedVariantId.value)||null);function variantPrice(v:any){const n=Number(v?.price);return v&&Number.isFinite(n)&&n>0?n:Number(configProduct.value?.price||0)}const addonOptions=computed(()=>configAddons.value.flatMap((g:any)=>(g.product_addon_options||[]).map((o:any)=>({...o,group:g}))));const selectedAddonOptions=computed(()=>addonOptions.value.filter((o:any)=>selectedAddonIds.value.includes(String(o.id))));const configuredPrice=computed(()=>Number(sitePrice.value??variantPrice(selectedVariant.value))+selectedAddonOptions.value.reduce((n:number,o:any)=>n+Number(o.price||0),0));
function selectedAddonForGroup(g:any){const ids=new Set((g.product_addon_options||[]).map((o:any)=>String(o.id)));return selectedAddonIds.value.find(id=>ids.has(id))||''}function selectSingleAddon(g:any,o:any){const ids=new Set((g.product_addon_options||[]).map((x:any)=>String(x.id)));selectedAddonIds.value=selectedAddonIds.value.filter(id=>!ids.has(id));selectedAddonIds.value.push(String(o.id))}
async function refreshSitePrice(){if(!configProduct.value||!q.value?.customer_id)return;try{const r:any=await adminFetch('/api/admin/manual-quotes/pricing',{method:'POST',body:{customerId:q.value.customer_id,productId:configProduct.value.id,variantId:selectedVariant.value?.id||null}});sitePrice.value=Number(r.price||0);standardSitePrice.value=Number(r.standardPrice||r.price||0);quotePricingLevel.value=r.pricingLevel}catch(e:any){configError.value=e?.data?.statusMessage||e.message;sitePrice.value=null;standardSitePrice.value=null;quotePricingLevel.value=null}}
async function configureProduct(p:any){configProduct.value=p;configVariants.value=[];configAddons.value=[];selectedVariantId.value='';selectedAddonIds.value=[];configError.value='';sitePrice.value=null;standardSitePrice.value=null;quotePricingLevel.value=null;showProducts.value=false;configLoading.value=true;try{[configVariants.value,configAddons.value]=await Promise.all([adminFetch(`/api/admin/products/${p.id}/variants`),adminFetch(`/api/admin/products/${p.id}/addons`)]) as any;await refreshSitePrice()}catch(e:any){configError.value=e?.data?.statusMessage||e.message}finally{configLoading.value=false}}
function closeConfigurator(){configProduct.value=null;configVariants.value=[];configAddons.value=[];selectedAddonIds.value=[];selectedVariantId.value='';sitePrice.value=null;standardSitePrice.value=null;quotePricingLevel.value=null}
function addConfiguredProduct(){for(const g of configAddons.value.filter((x:any)=>x.active!==false&&x.required)){if(!selectedAddonForGroup(g)){configError.value=`Please select an option for ${g.name}.`;return}}const p=configProduct.value,v=selectedVariant.value;q.value.manual_quote_items.push({product_id:p.id,variant_id:v?.id||null,item_type:'product',product_name:p.name,description:p.name,sku:v?.product_code||p.product_code||p.sku||'',quantity:1,unit_price:configuredPrice.value,discount_percent:0});productSearch.value='';closeConfigurator()}
function addManual(type:string){q.value.manual_quote_items.push({product_id:null,variant_id:null,item_type:type,product_name:type==='service'?'Service / Labour':'Custom Item',description:type==='service'?'Service / Labour':'Custom Item',sku:type==='service'?'LAB':'',quantity:1,unit_price:type==='service'?88:0,discount_percent:0})}
async function save(){saving.value=true;err.value='';try{q.value=await adminFetch(`/api/admin/manual-quotes/${q.value.id}`,{method:'PUT',body:{...q.value,items:q.value.manual_quote_items}});msg.value='Quote saved.'}catch(e:any){err.value=e?.data?.statusMessage||e.message}finally{saving.value=false}}async function email(){await save();try{await adminFetch(`/api/admin/manual-quotes/${q.value.id}/email`,{method:'POST'});q.value.status='sent';msg.value='Quote PDF emailed to the customer.'}catch(e:any){err.value=e?.data?.statusMessage||e.message}}async function duplicate(){const x:any=await adminFetch(`/api/admin/manual-quotes/${q.value.id}/duplicate`,{method:'POST'});await navigateTo(`/admin/manual-quotes/${x.id}`)}watch(selectedVariantId,()=>{if(configProduct.value)refreshSitePrice()});
watch(()=>q.value?.customer_id,()=>{deliveryPostcode.value=customerPostcode();if(q.value?.delivery_method==='delivery')calculateQuoteFreight()});
watch(()=>q.value?.delivery_method,(method)=>{if(!q.value)return;if(method==='pickup'||method==='none'){q.value.delivery_amount=0;freightRates.value=[];freightMessage.value=''}else if(method==='delivery'){deliveryPostcode.value=deliveryPostcode.value||customerPostcode();calculateQuoteFreight()}});
onMounted(load)
</script><style scoped>.input{@apply w-full rounded-lg border border-slate-300 bg-white px-3 py-2.5 text-sm}.label{@apply mb-1 block text-sm font-bold text-slate-700}.btn-primary{@apply rounded-lg bg-blue-600 px-5 py-2.5 text-sm font-bold text-white hover:bg-blue-700 disabled:opacity-50}.btn-secondary{@apply rounded-lg border border-slate-300 bg-white px-4 py-2.5 text-sm font-bold text-slate-700 hover:bg-slate-50}.admin-panel{@apply rounded-xl border border-slate-200 bg-white shadow-sm}</style>
